  ('fact_uuc_phc_indicators','elcac_brgy',9,'boolean',null,'True where the barangay is ELCAC-designated as conflict-affected. Qualifies on its own, independent of the armed_conf and idp shares.',null,'dimension',false,null,true),
  ('fact_uuc_phc_indicators','imr',10,'numeric',null,'Infant mortality rate. Bounded at 1,000 during cleaning where the source recorded more; check capped_indicators before quoting this value.','per 1,000 live births','measure',false,null,true),
  ('fact_uuc_phc_indicators','ufmr',11,'numeric',null,'Under-five mortality rate. Bounded at 1,000 during cleaning where the source recorded more; check capped_indicators before quoting this value.','per 1,000 live births','measure',false,null,true),
  ('fact_uuc_phc_indicators','fic',12,'numeric',null,'Fully immunized child coverage. Bounded at 100 during cleaning where the source recorded more; check capped_indicators before quoting this value.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','abr',13,'numeric',null,'Adolescent birth rate. Bounded at 1,000 during cleaning where the source recorded more; check capped_indicators before quoting this value.','per 1,000 women aged 10-19','measure',false,null,true),
  ('fact_uuc_phc_indicators','pre_natal',14,'numeric',null,'Pre-natal care coverage. Bounded at 100 during cleaning where the source recorded more; check capped_indicators before quoting this value.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','sba',15,'numeric',null,'Skilled birth attendance coverage. Bounded at 100 during cleaning where the source recorded more; check capped_indicators before quoting this value.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','water',16,'numeric',null,'Access to safe water coverage. Bounded at 100 during cleaning where the source recorded more; check capped_indicators before quoting this value.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','imr_prov_ref',17,'numeric',null,'Provincial benchmark for infant mortality rate that criterion (d) compares this barangay against. NULL where the source supplied #N/A - 57 barangays in 2 provinces (Nueva Vizcaya, Zamboanga City). A further 169 barangays in 3 provinces carry a value that cannot support the comparison at all - a placeholder 1, a zero, or a fraction - so criterion (d) is not evaluable for 226 barangays in 5 provinces, not merely for the 57 with no value here. Test it as: the largest of this barangay seven benchmarks is null or at most 1. Never capped, unlike the barangay value beside it.','per 1,000 live births','measure',false,null,true),
  ('fact_uuc_phc_indicators','ufmr_prov_ref',18,'numeric',null,'Provincial benchmark for under-five mortality rate that criterion (d) compares this barangay against. NULL where the source supplied #N/A - 57 barangays in 2 provinces (Nueva Vizcaya, Zamboanga City). A further 169 barangays in 3 provinces carry a value that cannot support the comparison at all - a placeholder 1, a zero, or a fraction - so criterion (d) is not evaluable for 226 barangays in 5 provinces, not merely for the 57 with no value here. Test it as: the largest of this barangay seven benchmarks is null or at most 1. Never capped, unlike the barangay value beside it.','per 1,000 live births','measure',false,null,true),
  ('fact_uuc_phc_indicators','fic_prov_ref',19,'numeric',null,'Provincial benchmark for fully immunized child coverage that criterion (d) compares this barangay against. NULL where the source supplied #N/A - 57 barangays in 2 provinces (Nueva Vizcaya, Zamboanga City). A further 169 barangays in 3 provinces carry a value that cannot support the comparison at all - a placeholder 1, a zero, or a fraction - so criterion (d) is not evaluable for 226 barangays in 5 provinces, not merely for the 57 with no value here. Test it as: the largest of this barangay seven benchmarks is null or at most 1. Never capped, unlike the barangay value beside it.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','abr_prov_ref',20,'numeric',null,'Provincial benchmark for adolescent birth rate that criterion (d) compares this barangay against. NULL where the source supplied #N/A - 57 barangays in 2 provinces (Nueva Vizcaya, Zamboanga City). A further 169 barangays in 3 provinces carry a value that cannot support the comparison at all - a placeholder 1, a zero, or a fraction - so criterion (d) is not evaluable for 226 barangays in 5 provinces, not merely for the 57 with no value here. Test it as: the largest of this barangay seven benchmarks is null or at most 1. Never capped, unlike the barangay value beside it.','per 1,000 women aged 10-19','measure',false,null,true),
  ('fact_uuc_phc_indicators','pre_natal_prov_ref',21,'numeric',null,'Provincial benchmark for pre-natal care coverage that criterion (d) compares this barangay against. NULL where the source supplied #N/A - 57 barangays in 2 provinces (Nueva Vizcaya, Zamboanga City). A further 169 barangays in 3 provinces carry a value that cannot support the comparison at all - a placeholder 1, a zero, or a fraction - so criterion (d) is not evaluable for 226 barangays in 5 provinces, not merely for the 57 with no value here. Test it as: the largest of this barangay seven benchmarks is null or at most 1. Never capped, unlike the barangay value beside it.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','sba_prov_ref',22,'numeric',null,'Provincial benchmark for skilled birth attendance coverage that criterion (d) compares this barangay against. NULL where the source supplied #N/A - 57 barangays in 2 provinces (Nueva Vizcaya, Zamboanga City). A further 169 barangays in 3 provinces carry a value that cannot support the comparison at all - a placeholder 1, a zero, or a fraction - so criterion (d) is not evaluable for 226 barangays in 5 provinces, not merely for the 57 with no value here. Test it as: the largest of this barangay seven benchmarks is null or at most 1. Never capped, unlike the barangay value beside it.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','water_prov_ref',23,'numeric',null,'Provincial benchmark for access to safe water coverage that criterion (d) compares this barangay against. NULL where the source supplied #N/A - 57 barangays in 2 provinces (Nueva Vizcaya, Zamboanga City). A further 169 barangays in 3 provinces carry a value that cannot support the comparison at all - a placeholder 1, a zero, or a fraction - so criterion (d) is not evaluable for 226 barangays in 5 provinces, not merely for the 57 with no value here. Test it as: the largest of this barangay seven benchmarks is null or at most 1. Never capped, unlike the barangay value beside it.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','capped_indicators',24,'text[]',null,'Which of THIS barangay values were bounded during cleaning, by column name (for example {water,fic}); empty for the 4,594 barangays whose values were all in range. 1,584 values across 1,397 barangays were recorded outside any possible range and bounded - coverage percentages at 100, rates at 1,000 - so 886 Water and 456 FIC values now read as exactly 100 with nothing else to distinguish them from genuine full coverage. A value named here is a ceiling, not a measurement: report it as bounded and its true figure as unknown, and never average or rank it.',null,'dimension',false,null,true),
  ('fact_uuc_phc_indicators','health_indicators',25,'smallint','0-7','The source office own criterion (d) score: how many of the seven health assessments this barangay failed against its province. Loaded as supplied and NOT recomputable from the indicator and benchmark columns in this table - the source scored it before cleaning bounded the values, using Pass/Fail columns the extract drops. A recomputation from the published columns disagrees on 664 rows. 4 or more is the qualifying threshold, and it is the fourth of the four socio-economic routes. Not evaluable for 226 barangays in 5 provinces whose provincial benchmarks are placeholders, zeroes, missing or fractions; exclude those before quoting any share of this route.','count of 7','measure',false,null,true),
  -- ref_uuc_phc_provincial (a view; registered because the read layer and queryDataset treat it as a table)
  ('ref_uuc_phc_provincial','province_code',1,'text',null,'Province the benchmarks apply to, as dim_geo codes it - never the source province name, 9 of which do not match dim_geo.',null,'key',true,'dim_geo.geo_code',true),
  ('ref_uuc_phc_provincial','n_listed_barangays',2,'integer',null,'Listed barangays in this province.','count','measure',false,null,true),
  ('ref_uuc_phc_provincial','n_with_reference',3,'integer',null,'How many of those barangays actually carry a reference value. Where this is below n_listed_barangays the benchmark rests on a subset - in province 09317 on 1 barangay of 8 - so read it before quoting the province figure.','count','measure',false,null,true),
  ('ref_uuc_phc_provincial','ref_imr',4,'numeric',null,'Provincial benchmark for infant mortality rate. NULL where no listed barangay in the province carries one.','per 1,000 live births','measure',false,null,true),
  ('ref_uuc_phc_provincial','ref_ufmr',5,'numeric',null,'Provincial benchmark for under-five mortality rate. NULL where no listed barangay in the province carries one.','per 1,000 live births','measure',false,null,true),
  ('ref_uuc_phc_provincial','ref_fic',6,'numeric',null,'Provincial benchmark for fully immunized child coverage. NULL where no listed barangay in the province carries one.','percent (0-100)','measure',false,null,true),
  ('ref_uuc_phc_provincial','ref_abr',7,'numeric',null,'Provincial benchmark for adolescent birth rate. NULL where no listed barangay in the province carries one.','per 1,000 women aged 10-19','measure',false,null,true),
  ('ref_uuc_phc_provincial','ref_pre_natal',8,'numeric',null,'Provincial benchmark for pre-natal care coverage. NULL where no listed barangay in the province carries one.','percent (0-100)','measure',false,null,true),
  ('ref_uuc_phc_provincial','ref_sba',9,'numeric',null,'Provincial benchmark for skilled birth attendance coverage. NULL where no listed barangay in the province carries one.','percent (0-100)','measure',false,null,true),
  ('ref_uuc_phc_provincial','ref_water',10,'numeric',null,'Provincial benchmark for access to safe water coverage. NULL where no listed barangay in the province carries one.','percent (0-100)','measure',false,null,true),
  -- ref_uuc_phc_quality
  ('ref_uuc_phc_quality','n_listed',1,'integer',null,'Barangays on the 2025 list - the denominator every share on the data-quality page is taken against.','count','measure',false,null,true),
  ('ref_uuc_phc_quality','n_barangays_capped',2,'integer',null,'BARANGAYS carrying at least one value bounded during cleaning: 1,397. NOT the number of bounded values, which is 1,584 - see n_values_capped. Quoting the wrong one of these two overstates the affected share of the list by about 13 percent.','count','measure',false,null,true),
  ('ref_uuc_phc_quality','n_values_capped',3,'integer',null,'VALUES bounded during cleaning across all seven boundable indicators: 1,584. Larger than n_barangays_capped because 167 barangays carry more than one. Equal to the sum of agg_uuc_phc_indicator_dist bin_capped over the national rows; the migration aborts if the two disagree.','count','measure',false,null,true),
  ('ref_uuc_phc_quality','n_barangays_multi_capped',4,'integer',null,'Barangays carrying more than one bounded value: 167. This is the whole difference between the barangay count and the value count.','count','measure',false,null,true),
  ('ref_uuc_phc_quality','n_score_disagreement',5,'integer',null,'Listed barangays where recomputing criterion (d) from the published columns gives a different answer from the score the source office recorded: 664. A MEASUREMENT OF A GAP, NOT A CORRECTION - the source scored the values before cleaning bounded them, so the recomputation is a different quantity wearing the same name.','count','measure',false,null,true),
  ('ref_uuc_phc_quality','n_score_understated',6,'integer',null,'Of n_score_disagreement, how many recompute LOWER than the recorded score. Currently all of them, which is what capping the values would predict.','count','measure',false,null,true),
  ('ref_uuc_phc_quality','n_no_route_if_recomputed',7,'integer',null,'Listed barangays that would qualify on NO route at all if criterion (d) were recomputed from the published columns: 98. DOH AO No. 2020-0023 makes that impossible - a barangay reaches this list only with a socio-economic factor present - which is the evidence that the recomputation is wrong rather than merely different.','count','measure',false,null,true),
  ('ref_uuc_phc_quality','n_no_route_as_recorded',8,'integer',null,'The same count against the source own recorded score: 0. The pair of this and n_no_route_if_recomputed is the argument for loading health_indicators rather than deriving it.','count','measure',false,null,true),
  -- ref_uuc_phc_benchmark_gaps
  ('ref_uuc_phc_benchmark_gaps','province_code',1,'text',null,'Province the finding applies to.',null,'key',true,'dim_geo.geo_code',true),
  ('ref_uuc_phc_benchmark_gaps','n_listed_province',2,'integer',null,'Listed barangays in this province in total - read beside n_affected, which can be smaller.','count','measure',false,null,true),
  ('ref_uuc_phc_benchmark_gaps','kind',3,'text','no reference supplied|every value zero|every value exactly 1|fractions where percentages were wanted|FIC benchmark above the 100 ceiling barangay values were bounded to','What is wrong with this province benchmarks, in words. Computed from the values themselves, never from a list of province codes.',null,'dimension',false,null,true),
  ('ref_uuc_phc_benchmark_gaps','n_affected',4,'integer',null,'Barangays in this province the finding applies to. Not always the province whole listed count: in province 09317 only 7 of 8 lack a reference.','count','measure',false,null,true),
  ('ref_uuc_phc_benchmark_gaps','witness_value',5,'numeric',null,'The value that identifies the finding - the largest of the seven benchmarks for a criterion_d row (1, or 0, or a fraction; NULL where none was supplied), or the FIC benchmark itself for a fic_only row.',null,'measure',false,null,true),
  ('ref_uuc_phc_benchmark_gaps','finding',6,'text','criterion_d|fic_only','WHICH finding this row is, so the two are never added together. criterion_d rows total 226 barangays whose whole benchmark set cannot support criterion (d); fic_only rows total 113 barangays affected on the FIC comparison alone and still evaluable on the other six indicators.',null,'dimension',false,null,true),
  -- ref_uuc_phc_published_delta
  ('ref_uuc_phc_published_delta','id',1,'bigint',null,'Surrogate row identifier; carries no meaning.',null,'meta',false,null,false),
  ('ref_uuc_phc_published_delta','dataset_id',2,'bigint',null,'Source dataset this row belongs to.',null,'key',true,'dim_dataset.dataset_id',true),
  ('ref_uuc_phc_published_delta','geo_code',3,'text',null,'Geography that differs. PH for the national total.',null,'key',true,'dim_geo.geo_code',true),
  ('ref_uuc_phc_published_delta','geo_level',4,'geo_level_enum','national|region','Level of the differing geography. Only these two levels are reconciled - the cue cards publish no figure below region.',null,'dimension',false,null,true),
  ('ref_uuc_phc_published_delta','source_label',5,'text',null,'The label exactly as the cue cards print it, so a reader can find the row in the source. TOTAL for the national row.',null,'dimension',false,null,true),
  ('ref_uuc_phc_published_delta','n_published',6,'integer',null,'What the 2027 Budget Cue Cards p37 publish for this geography. Always quote it with source_as_of: it is a snapshot as of that date, not a current figure.','count','measure',false,null,true),
  ('ref_uuc_phc_published_delta','n_listed',7,'integer',null,'What this dashboard publishes for the same geography, from agg_uuc_phc_counts.','count','measure',false,null,true),
  ('ref_uuc_phc_published_delta','delta',8,'integer',null,'n_listed minus n_published. Never zero - geographies where the two sources agree are not stored, so the absence of a row means agreement.','count','measure',false,null,true),
  ('ref_uuc_phc_published_delta','source_doc_key',9,'text',null,'doc_source key of the document the published figure was read from.',null,'key',false,null,true),
  ('ref_uuc_phc_published_delta','source_page',10,'integer',null,'Page of that document carrying the figure.',null,'dimension',false,null,true),
  ('ref_uuc_phc_published_delta','source_as_of',11,'date',null,'The date the published document speaks as of. The likeliest reading of the difference is a vintage gap, but NEITHER SOURCE STATES THAT - report the date and the delta, never a cause.',null,'dimension',false,null,true)
) as c (
  table_name, column_name, ordinal, data_type, allowed_values,
  meaning, unit, role, is_join_key, joins_to, is_queryable
)
join dataset_registry r on r.table_name = c.table_name
on conflict (registry_id, column_name) do update set
  ordinal = excluded.ordinal,
  data_type = excluded.data_type,
  allowed_values = excluded.allowed_values,
  meaning = excluded.meaning,
  unit = excluded.unit,
  role = excluded.role,
  is_join_key = excluded.is_join_key,
  joins_to = excluded.joins_to,
  is_queryable = excluded.is_queryable,
  status = excluded.status;
